'use strict';
let RecapIndex=null,recapCategory='all',recapQuery='',recapLimit=80,recapSummer=true;
const recapCategories={all:'전체',worldcup:'월드컵',international:'국가대표 대회',league:'리그·우승',europe:'유럽대항전',transfer:'빅이적',retirement:'은퇴',goals:'득점왕',assists:'도움왕',ballon:'발롱도르',issue:'이슈·사건'};
async function loadSeasonRecapContext(){
 if(state.view!=='recap')return null;
 if(!RecapIndex)RecapIndex=await load('season-recaps/index.json');
 const year=state.recapYear??SeasonRecapEngine.seasonFor(state.date),meta=RecapIndex.seasons[year];
 if(!meta)return {year,data:{season:year,events:[]},summer:null};
 const [data,summer]=await Promise.all([load(meta.file),recapSummer&&RecapIndex.seasons[year+1]?load(RecapIndex.seasons[year+1].file):Promise.resolve(null)]);
 return {year,data,summer};
}
function seasonRecapPrompt(){const month=+state.date.slice(5,7),current=SeasonRecapEngine.seasonFor(state.date),year=month>=7&&month<=8?current-1:current;return `<section class="recap-day-prompt"><div><small>SEASON IN REVIEW</small><h3>${year}/${String(year+1).slice(-2)} · 한 시즌을 한눈에</h3><p>우승부터 이적·은퇴·수상·이슈까지, 지난 기록을 날짜순으로 모았습니다.</p></div><button class="primary" data-recap-open="${year}">시즌 회고 열기 ↗</button></section>`}
function recapVisible(){return SeasonRecapEngine.visible(context.recap?.data,context.recap?.summer,{...state,includeSummer:recapSummer})}
function recapFiltered(){let rows=recapVisible();if(recapCategory!=='all')rows=rows.filter(e=>e.category===recapCategory);let q=recapQuery.toLowerCase();return q?rows.filter(e=>[e.title,e.text,n(e.winner||''),...(e.winners||[]).map(n),...(e.people||[]).map(koreanPerson),n(e.origin||''),n(e.dest||'')].join(' ').toLowerCase().includes(q)):rows}
function recapEndDate(){const c=context.recap||{},base=c.data?.reviewEnd||c.data?.nominalEnd;let dates=[base,...(c.data?.events||[]).map(e=>e.date)];if(recapSummer)dates.push(...(c.summer?.events||[]).filter(e=>e.summer&&e.date>=`${+c.year+1}-07-01`&&e.date<=`${+c.year+1}-08-31`).map(e=>e.date));return dates.filter(Boolean).sort().at(-1)}
function seasonRecapView(){
 const c=context.recap||{},year=c.year??SeasonRecapEngine.seasonFor(state.date),rows=recapVisible(),ended=state.date>recapEndDate()||(state.date===recapEndDate()&&state.closed.includes(state.date)),titles=rows.filter(e=>['league','europe','worldcup','international'].includes(e.category)&&e.winner),awards=rows.filter(e=>['goals','assists','ballon'].includes(e.category)),counts={};for(let e of rows)counts[e.category]=(counts[e.category]||0)+1;
 return `<section class="season-recap-hero"><div class="recap-hero-top"><span class="eyebrow">THE SEASON, IN PERSPECTIVE</span><span class="recap-state">${ended?'시즌 회고':state.date>c.data?.nominalEnd?'시즌 종료 · 이 날짜까지의 회고':'진행 중 · 이 날짜까지'}</span></div><h2>${year}<span>/ ${String(+year+1).slice(-2)}</span></h2><h3>그 시즌을 만든 순간들.</h3><p>들어 올린 트로피, 새로운 유니폼, 마지막 인사.<br>경기장 안팎의 이야기를 하나의 타임라인으로.</p><div class="recap-hero-stats"><span><b>${titles.length}</b> 우승 기록</span><span><b>${counts.transfer||0}</b> 주요 이적·보도</span><span><b>${awards.length}</b> 개인 수상·선두</span><span><b>${rows.length}</b> 공개된 회고 항목</span></div></section><div class="recap-controls"><label>시즌 <select id="recapSeason" aria-label="회고 시즌">${Object.keys(RecapIndex?.seasons||{}).map(y=>`<option value="${y}" ${+y===+year?'selected':''}>${y}/${String(+y+1).slice(-2)}${+y===1955?' · 일부 기간':''}</option>`).join('')}</select></label><label class="recap-summer"><input id="recapSummer" type="checkbox" ${recapSummer?'checked':''}> 이어지는 여름 월드컵·유로 함께 보기</label><button class="text-button" id="recapToEnd" ${recapEndDate()>manifest.cutoff?'disabled':''}>회고 마지막 기록까지 날짜 이동 ↗</button><button class="text-button" id="recapPrint">회고 저장·인쇄 ↗</button></div><div class="recap-date-note"><b>${year}.07 — ${+year+1}.06</b><span>기본 시즌은 7월~다음 해 6월입니다. ${state.date}까지 지난 기록만 표시합니다. 여름 확장과 순연 대회·후일 행정 결정·관련 개인상은 원래 발표 날짜를 유지합니다. 시즌·연도 단위 항목의 공개 기준일은 실제 발표일과 다릅니다.</span></div>${titles.length?`<section class="recap-trophy-section"><div class="recap-section-head"><h3>이 시즌의 챔피언들</h3><small>현재 날짜까지 확인된 우승</small></div><div class="recap-trophies">${titles.map(e=>`<article>${crestHTML(e.winner,{date:e.date,size:'large'})}<small>${esc(e.title)}</small><b>${(e.winners||[e.winner]).map(t=>esc(n(t))).join(' · ')}</b><span>${e.precision==='season'?'시즌 기록':e.date}</span></article>`).join('')}</div></section>`:''}<div class="recap-section-head"><h3>시즌 타임라인</h3><small>결과 · 발표 · 등록 · 후대 기록의 출처를 구분합니다</small></div><div class="recap-filter-bar">${Object.entries(recapCategories).map(([k,label])=>`<button data-recap-filter="${k}" class="${recapCategory===k?'active':''}" aria-pressed="${recapCategory===k}">${label}${k!=='all'&&counts[k]?`<span>${counts[k]}</span>`:''}</button>`).join('')}</div><label class="archive-search recap-search"><span>⌕</span><input id="recapSearch" type="search" value="${esc(recapQuery)}" placeholder="선수·팀·사건으로 시즌 돌아보기" aria-label="시즌 회고 검색"></label><div id="recapTimeline">${recapTimelineHTML()}</div><details class="recap-coverage"><summary>기록의 범위와 날짜 기준</summary><p>발롱도르의 평가 연도와 발표 연도를 구분합니다. 2010~2015년 수상은 다음 해 시상식 날짜에 표시합니다. 2022년부터는 평가 대상 시즌에 연결하고 실제 발표일을 유지합니다. 옛 발표일이 없는 연간 기록은 연말에, 리그 우승·득점·도움 기록은 보수적인 시즌 결산 기준일에 공개합니다.</p><p>공식 Playmaker 수상, 출처의 득점 선두, 개인 출전 자료로 계산한 선두는 서로 다른 종류입니다. 도움의 집계 정의가 제공자마다 다를 수 있습니다. 이적·은퇴 등록일도 공식 발표일이나 마지막 경기일과 같다고 단정하지 않습니다.</p><p>모든 나라의 우승·수상·은퇴와 기사 전체가 수록된 것은 아닙니다. 빈 항목은 미수록이며, 여름 국가대표 대회는 이웃한 시즌 회고에도 보일 수 있습니다. 당시 보도와 후대 사건 정리는 각 카드의 근거로 구분합니다.</p></details>`;
}
function recapTimelineHTML(){
 const rows=recapFiltered(),shown=rows.slice(0,recapLimit);let month='';
 return `<p class="recap-results-count">현재 조건 ${rows.length.toLocaleString()}개 기록 · 날짜순</p><div class="recap-timeline">${shown.map(e=>{let key=e.date.slice(0,7),head=key!==month?`<div class="recap-month"><span>${e.date.slice(0,4)}</span><b>${+e.date.slice(5,7)}월</b></div>`:'';month=key;const precision={year:'연도 단위 · 정확한 날짜 미확인',season:'시즌 결산 · 확정일 별도 미확인',registration:'등록일 기준'},dateLabel=e.precision==='year'?e.date.slice(0,4)+'년':e.precision==='season'?'시즌 결산':e.date.replaceAll('-','.');return head+`<article class="recap-event recap-${e.category}" data-recap-event="${e.id}" data-recap-date="${e.date}"><div class="recap-event-rail"><span></span><time>${dateLabel}</time></div><div class="recap-event-card"><div class="recap-event-meta"><b>${esc(recapCategories[e.category]||e.category)}</b>${e.summer?'<small>여름 국가대표 대회</small>':''}<span>${esc(e.basis)}</span></div><h4>${esc(e.title)}</h4>${e.winner?`<div class="recap-winner">${(e.winners||[e.winner]).map(t=>teamLabel(t,{date:e.date})).join(' · ')}</div>`:''}${e.people?.length?`<div class="recap-people">${e.people.map(p=>esc(koreanPerson(p))).join(' · ')}${e.value!==undefined?` <strong>${Number(e.value).toLocaleString()}${esc(e.unit)}</strong>`:''}</div>`:''}${e.origin?`<div class="recap-transfer-path">${teamLabel(e.origin,{date:e.date})}<span>→</span>${teamLabel(e.dest,{date:e.date})}</div>`:''}${e.feeEur?`<small class="recap-fee">원자료 기본 이적료 €${Number(e.feeEur).toLocaleString()}</small>`:''}<p>${esc(e.text)}</p>${precision[e.precision]?`<div class="recap-precision">${precision[e.precision]} · 공개 기준 ${e.date}</div>`:''}<footer><a class="source-link" href="${esc(e.source)}" target="_blank" rel="noopener">근거 자료 ↗</a>${e.cup?`<button class="text-button" data-recap-cup="${esc(e.cup)}" data-recap-on="${e.date}">당시 대진·경기 ↗</button>`:''}${e.league?`<button class="text-button" data-recap-league="${esc(e.league)}" data-recap-year="${e.leagueSeason??e.season}">수록 시즌 순위표 ↗</button>`:''}${e.player?`<button class="text-button" data-recap-player="${esc(e.player)}">선수 경력 ↗</button>`:''}</footer></div></article>`}).join('')||'<div class="edition-empty">이 날짜까지 이 조건으로 공개할 회고 기록이 없습니다. 날짜를 뒤로 넘기거나 다른 분류를 선택해 주세요.</div>'}</div>${rows.length>recapLimit?'<button class="show-more" id="moreRecap">시즌 기록 더 보기 ↓</button><button class="text-button" id="allRecap">한 번에 모두 펼치기 ↗</button>':''}`;
}
document.addEventListener('change',e=>{if(e.target.id==='recapSeason'){state.recapYear=+e.target.value;recapLimit=80;refresh()}if(e.target.id==='recapSummer'){recapSummer=e.target.checked;recapLimit=80;refresh()}});
document.addEventListener('input',e=>{if(e.target.id==='recapSearch'){recapQuery=e.target.value;recapLimit=80;$('#recapTimeline').innerHTML=recapTimelineHTML()}});
document.addEventListener('click',async e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.recapOpen){state.recapYear=+b.dataset.recapOpen;state.view='recap';recapCategory='all';recapLimit=80;refresh()}if(b.dataset.recapFilter){recapCategory=b.dataset.recapFilter;recapLimit=80;render()}if(b.id==='moreRecap'||b.id==='allRecap'){recapLimit=b.id==='allRecap'?Infinity:recapLimit+80;$('#recapTimeline').innerHTML=recapTimelineHTML()}if(b.id==='recapToEnd'){state.recapYear=context.recap.year;let end=recapEndDate();if(end<=manifest.cutoff){let d=new Date(end+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+1);let next=d.toISOString().slice(0,10);if(next<=manifest.cutoff)goDate(next)}}if(b.id==='recapPrint'){recapLimit=Infinity;render();window.print()}if(b.dataset.recapCup){state.cup=b.dataset.recapCup;state.date=b.dataset.recapOn;state.closed=[...new Set([...state.closed,state.date])];state.view='cups';refresh()}if(b.dataset.recapLeague){const info=manifest.leagues[b.dataset.recapLeague]?.seasons.find(s=>s.year===+b.dataset.recapYear);if(info){state.league=b.dataset.recapLeague;state.date=info.end;state.closed=[...new Set([...state.closed,state.date])];state.view='leagues';refresh()}}if(b.dataset.recapPlayer){state.selectedPlayer=b.dataset.recapPlayer;state.view='players';refresh()}});
